#include <stdio.h>
#include <string.h>
#define main perf_summary_main
#include "../src/perf_summary.c"
#undef main
static void reset_events(void){const char*n[]={"cycles","instructions","cache-misses"};memset(events,0,sizeof events);for(size_t i=0;i<3;i++){events[i].name=n[i];strcpy(events[i].count,"NA");strcpy(events[i].scope,"NA");strcpy(events[i].running,"NA");}}
int main(int argc,char**argv){if(argc!=4){fputs("usage: perf test RAW SCOPE_RAW OUTPUT\n",stderr);return 2;}remove(argv[3]);char notes[4096];snprintf(notes,sizeof notes,"%s",argv[3]);char*dot=strrchr(notes,'.');if(dot)strcpy(dot,".notes.txt");else strcat(notes,".notes.txt");remove(notes);char*args[]={"perf_summary",argv[1],argv[3],NULL};if(perf_summary_main(3,args)!=0)return 3;FILE*f=fopen(argv[3],"rb");if(!f)return 4;char text[2048];size_t n=fread(text,1,sizeof text-1,f);text[n]=0;fclose(f);if(!strstr(text,"cycles,100000,user,99.5")||!strstr(text,"instructions,250000,user,99.5")||!strstr(text,"cache-misses,NA,user,0")||!strstr(text,"ipc,2.5,user,NA"))return 5;f=fopen(notes,"rb");if(!f)return 6;n=fread(text,1,sizeof text-1,f);text[n]=0;fclose(f);if(!strstr(text,"permission")||!strstr(text,"shifted")||!strstr(text,"malformed row"))return 7;if(perf_summary_main(3,args)==0)return 8;remove(argv[3]);remove(notes);reset_events();char*scope_args[]={"perf_summary",argv[2],argv[3],NULL};if(perf_summary_main(3,scope_args)!=0)return 9;f=fopen(argv[3],"rb");if(!f)return 10;n=fread(text,1,sizeof text-1,f);text[n]=0;fclose(f);if(!strstr(text,"ipc,NA,NA,NA"))return 11;remove(argv[3]);remove(notes);puts("native perf parser tests PASS");return 0;}
